using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    private static readonly string[] AutomationModes={"Read","Write","Touch","Latch"};
    private static RefCounted Recording(Control o)=>Field<RefCounted>(o,"automation_recording");
    private static double Position(Control o)=>Field<Node>(o,"playback").Get("position").AsDouble();
    public void build_automation_controls(Control o,Node parent)
    {
        var row=new HFlowContainer();parent.AddChild(row);label(row,"Automation");var mode=new OptionButton();foreach(string item in AutomationModes)mode.AddItem(item);row.AddChild(mode);o.Set("_automation_mode",mode);mode.TooltipText="One armed parameter. Write overwrites while playing; Touch punches only while held; Latch holds after release until Stop. Stop saves one undo action and returns to Read.";mode.ItemSelected+=index=>{if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){_frameAutomation.discard(Recording(o),"Read: finish the audio take before recording automation.");return;}finish_automation_pass(o,"Mode changed");finish_control_edits(o);Session(o).Call("commit");Field<Control>(o,"canvas").Call("finish_automation_edit",true);o.CallDeferred("_arm_automation_mode",AutomationModes[(int)index],Session(o),o.Get("_interaction_epoch"));};ActionButton(row,"Target...",()=>automation_record_target_dialog(o));var target=Field<Label>(o,"_automation_target_label");target.CustomMinimumSize=new Vector2(180,0);row.AddChild(target);var fader=Field<HSlider>(o,"_automation_fader");fader.CustomMinimumSize=new Vector2(180,24);fader.Step=.001;row.AddChild(fader);bind_automation_fader(o,fader);ActionButton(row,"Finish pass",()=>finish_automation_pass(o,"Pass finished"));ActionButton(row,"Discard pass",()=>{_frameAutomation.discard(Recording(o),"Read: pending automation discarded.");refresh_automation_controls(o);});var status=Field<Label>(o,"_automation_status");status.AutowrapMode=TextServer.AutowrapMode.WordSmart;parent.AddChild(status);status.AddThemeFontSizeOverride("font_size",10);refresh_automation_controls(o);
    }
    public void bind_automation_fader(Control o,Slider fader)
    {
        bool held=false,blocked=false;long epoch=0;fader.DragStarted+=()=>{blocked=false;held=true;automation_gesture_start(o);epoch=o.Get("_interaction_epoch").AsInt64();};fader.ValueChanged+=value=>{if(blocked||held&&epoch!=o.Get("_interaction_epoch").AsInt64())return;if(Recording(o).Get("mode").AsString()!="Read")automation_control_changed(o,value);};void Finish(bool keep){bool valid=held&&epoch==o.Get("_interaction_epoch").AsInt64();if(held)blocked=true;held=false;if(valid){if(keep)automation_gesture_end(o);else{o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);_frameAutomation.discard(Recording(o),"Read: gesture cancelled.");}}}fader.DragEnded+=_=>{Finish(true);blocked=false;};fader.FocusExited+=()=>Finish(true);fader.FocusEntered+=()=>{if(!held)blocked=false;};fader.TreeExiting+=()=>Finish(true);fader.GuiInput+=input=>{if(input is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape){Finish(false);fader.AcceptEvent();}};
    }
    public void arm_automation_mode(Control o,string mode,RefCounted owner,long epoch){if(epoch!=o.Get("_interaction_epoch").AsInt64()||Session(o)!=owner||Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool())return;_frameAutomation.set_mode(Recording(o),mode);refresh_automation_controls(o);}
    public void automation_status_changed(Control o,string message)
    {
        var recording=Recording(o);string mode=recording.Get("mode").AsString();if(mode=="Read"){if(o.Get("_automation_gesture_held").AsBool())o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);o.Set("_automation_gesture_held",false);Field<Timer>(o,"_automation_release_timer").Stop();}Field<Label>(o,"_automation_status").Text=message;var selector=Field<OptionButton>(o,"_automation_mode");selector?.Select(Array.IndexOf(AutomationModes,mode));Field<HSlider>(o,"_automation_fader").Editable=mode!="Read"&&_frameAutomation.editable(recording);
    }
    public void refresh_automation_controls(Control o)
    {
        var recording=Recording(o);var info=_frameAutomation.info(recording);Field<Label>(o,"_automation_target_label").Text=Get(info,"label","Target unavailable").AsString();var fader=Field<HSlider>(o,"_automation_fader");if(info.Count>0){fader.MinValue=info["minimum"].AsDouble();fader.MaxValue=info["maximum"].AsDouble();fader.SetValueNoSignal(_frameAutomation.display_value(recording,Position(o)));}automation_status_changed(o,recording.Get("message").AsString());fader.TooltipText="Records the armed owner curve at the playhead. Clip/effect and already-rendered audio are capture-only until Stop and replay. Mouse release ends Touch; keyboard/numeric gestures release after 250 ms idle.";
    }
    public void automation_gesture_start(Control o){o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);Field<Timer>(o,"_automation_release_timer").Stop();o.Set("_automation_gesture_held",true);_frameAutomation.touch(Recording(o),Position(o));}
    public void automation_control_changed(Control o,double value){_frameAutomation.change(Recording(o),value,Position(o));if(!o.Get("_automation_gesture_held").AsBool())Field<Timer>(o,"_automation_release_timer").Start();}
    public void automation_gesture_end(Control o){o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);o.Set("_automation_gesture_held",false);Field<Timer>(o,"_automation_release_timer").Stop();_frameAutomation.release(Recording(o),Position(o));}
    public void finish_automation_pass(Control o,string reason){o.Set("_interaction_epoch",o.Get("_interaction_epoch").AsInt64()+1);Field<Timer>(o,"_automation_release_timer").Stop();o.Set("_automation_gesture_held",false);_frameAutomation.finish(Recording(o),reason);if(o.Get("_automation_mode").AsGodotObject()!=null)refresh_automation_controls(o);}
    public void automation_seek(Control o,double seconds,bool scrub){if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Stop or cancel the take before seeking.");return;}finish_automation_pass(o,"Seek ended the pass");Field<Node>(o,"playback").Call("seek",seconds,scrub);}
    public void choose_automation_record_target(Control o,Settings target,string laneId){finish_automation_pass(o,"Target changed");finish_control_edits(o);Session(o).Call("commit");Field<Control>(o,"canvas").Call("finish_automation_edit",true);_frameAutomation.choose(Recording(o),target,laneId);Field<Control>(Field<Node>(o,"_layout"),"automation_panel").Show();refresh_automation_controls(o);}
    public void automation_record_target_dialog(Control o)
    {
        finish_automation_pass(o,"Choosing an automation target");var dialog=window(o,"Record one automation parameter",new Vector2I(680,500));var windowNode=dialog["window"].As<Window>();windowNode.SetMeta("audio_lane_window",true);var host=dialog["host"].As<Node>();var owner=Session(o);label(host,"Choose an unlocked parameter, then Write, Touch or Latch above the timeline. Each pass uses one undo action. Clip points use local clip time. Native mixer gain/pan can be monitored live; clip/effect or exact-rendered audio is heard after replay.");var search=new LineEdit{PlaceholderText="Search owner or parameter"};host.AddChild(search);var scroller=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(scroller);var list=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroller.AddChild(list);void Rebuild(){clear(list);foreach(var info in _frameLanes.options(Document(o))){string text=info["label"].AsString();if(search.Text.Length>0&&!text.ToLowerInvariant().Contains(search.Text.ToLowerInvariant()))continue;ActionButton(list,text,()=>{if(Session(o)!=owner){windowNode.QueueFree();return;}choose_automation_record_target(o,info["target"].AsGodotDictionary(),"");windowNode.QueueFree();}).Disabled=info["locked"].AsBool();}}search.TextChanged+=_=>Rebuild();Rebuild();label(host,"30 Hz capture, linear decimation, 2,048 retained points, 64 gestures and one hour per pass. A loop wrap ends the pass. Unrelated edits cancel pending capture; Finish pass first to keep it. Offline curves retain the renderer's existing limits.");
    }
    public void update_automation_readouts(Control o)
    {
        if(o.Get("_automation_mode").AsGodotObject()==null)return;bool held=o.Get("_automation_gesture_held").AsBool(),idle=Field<Timer>(o,"_automation_release_timer").IsStopped();var recording=Recording(o);double position=Position(o);if(!held&&idle)Field<HSlider>(o,"_automation_fader").SetValueNoSignal(_frameAutomation.display_value(recording,position));if(!Field<Node>(o,"playback").Get("playing").AsBool()||Session(o).Get("_before").AsGodotObject()!=null)return;foreach(var raw in Items(o,"_automation_mixer_controls")){var entry=raw.AsGodotDictionary();var control=entry["control"].AsGodotObject();if(!GodotObject.IsInstanceValid(control))continue;var target=entry["target"].AsGodotDictionary();double value;if(_frameAutomation.matches(recording,target)){if(held||!idle)continue;value=_frameAutomation.display_value(recording,position);}else{var info=_frameLanes.resolve(Document(o),target);if(info.Count==0)continue;value=_frameLanes.value(_frameLanes.points(info),position,info["fallback"].AsDouble());}((Godot.Range)control).SetValueNoSignal(value);}
    }
    public void exit_tree(Control o){Field<Node>(o,"_optional_tools").Call("cancel");foreach(string method in new[]{"_close_portable_review","_close_recovery_review","_close_silence_review"})o.Call(method);o.Set("_record_cancel_requested",true);o.Set("_record_generation",o.Get("_record_generation").AsInt64()+1);o.Set("_record_prepared",default(Variant));o.Set("_record_loop_preview",default(Variant));o.Set("_record_loop_signature","");Field<Node>(o,"jobs").Call("cancel_kind","record_prepare");finish_control_edits(o);finish_automation_pass(o,"Workspace closed");}
}
